import React, { useState, useEffect } from 'react';
import { Plus, Search, X, Activity, Edit, Trash2 } from 'lucide-react';
import api from '../../services/api';
import toast from 'react-hot-toast';
import './Modules.css';

const Indicators = () => {
  const [indicators, setIndicators] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [editingId, setEditingId] = useState(null);

  const [formData, setFormData] = useState({
    name: '',
    output_category: '',
    baseline: 0,
    target: 0,
    actual: 0,
    frequency: '',
    unit_of_measure: '',
  });

  const loadIndicators = async () => {
    setLoading(true);
    try {
      const response = await api.get('/indicators/');
      setIndicators(Array.isArray(response.data) ? response.data : response.data.results || []);
    } catch (error) {
      console.error('Error loading indicators:', error);
      toast.error('Failed to load indicators.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadIndicators();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: name === 'baseline' || name === 'target' || name === 'actual' ? parseFloat(value) || 0 : value,
    }));
  };

  const handleClose = () => {
    setShowModal(false);
    setEditingId(null);
    setFormData({
      name: '',
      output_category: '',
      baseline: 0,
      target: 0,
      actual: 0,
      frequency: '',
      unit_of_measure: '',
    });
  };

  const handleEdit = (item) => {
    setFormData({
      name: item.name || '',
      output_category: item.output_category || '',
      baseline: item.baseline || 0,
      target: item.target || 0,
      actual: item.actual || 0,
      frequency: item.frequency || '',
      unit_of_measure: item.unit_of_measure || '',
    });
    setEditingId(item.id);
    setShowModal(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this indicator?')) {
      try {
        await api.delete(`/indicators/${id}/`);
        toast.success('Indicator deleted successfully!');
        loadIndicators();
      } catch (error) {
        console.error('Error deleting indicator:', error);
        toast.error('Failed to delete indicator.');
      }
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) {
        await api.put(`/indicators/${editingId}/`, formData);
        toast.success('Indicator updated successfully!');
      } else {
        await api.post('/indicators/', formData);
        toast.success('Indicator created successfully!');
      }
      handleClose();
      loadIndicators();
    } catch (error) {
      console.error('Error saving indicator:', error);
      toast.error('Failed to save indicator.');
    } finally {
      setSaving(false);
    }
  };

  const filteredIndicators = indicators.filter(
    (ind) =>
      ind.name?.toLowerCase().includes(search.toLowerCase()) ||
      ind.output_category?.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="module-container">
      <div className="module-header">
        <div>
          <h1>M&E Indicators</h1>
          <p>Track targets vs actuals for logframe indicators.</p>
        </div>
        <button className="btn-primary" onClick={() => setShowModal(true)}>
          <Plus size={18} /> New Indicator
        </button>
      </div>

      <div className="controls-row">
        <div className="search-input-wrapper">
          <Search size={18} className="search-icon" />
          <input
            type="text"
            placeholder="Search indicators..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
      </div>

      <div className="table-card">
        {loading ? (
          <div style={{ padding: '40px', textAlign: 'center', color: '#5a5c74' }}>Loading indicators...</div>
        ) : filteredIndicators.length === 0 ? (
          <div className="empty-state">
            <Activity size={48} className="empty-state-icon" />
            <p>No indicators found. Click "New Indicator" to add one.</p>
          </div>
        ) : (
          <table className="responsive-table">
            <thead>
              <tr>
                <th>Indicator Name</th>
                <th>Category</th>
                <th>Baseline</th>
                <th>Target</th>
                <th>Actual</th>
                <th>Progress</th>
                <th style={{ textAlign: 'right' }}>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredIndicators.map((ind) => {
                const target = parseFloat(ind.target) || 0;
                const actual = parseFloat(ind.actual) || 0;
                const progress = target > 0 ? Math.min(100, Math.round((actual / target) * 100)) : 0;
                let color = '#C94B4B'; // Red
                if (progress >= 100) color = '#2F9E68'; // Green
                else if (progress >= 50) color = '#F2994A'; // Amber

                return (
                  <tr key={ind.id}>
                    <td style={{ fontWeight: 600 }}>{ind.name}</td>
                    <td>{ind.output_category}</td>
                    <td>{ind.baseline} {ind.unit_of_measure}</td>
                    <td>{ind.target} {ind.unit_of_measure}</td>
                    <td style={{ fontWeight: 'bold' }}>{ind.actual} {ind.unit_of_measure}</td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <div style={{ width: '100px', height: '8px', background: '#e0e0e0', borderRadius: '4px', overflow: 'hidden' }}>
                          <div style={{ width: `${progress}%`, height: '100%', background: color }}></div>
                        </div>
                        <span style={{ fontSize: '12px', fontWeight: 'bold', color }}>{progress}%</span>
                      </div>
                    </td>
                    <td>
                      <div className="action-buttons-group">
                        <button className="btn-icon" title="Edit Indicator" onClick={() => handleEdit(ind)}>
                          <Edit size={14} style={{ color: '#2F9E68' }} />
                        </button>
                        <button className="btn-icon" title="Delete Indicator" onClick={() => handleDelete(ind.id)}>
                          <Trash2 size={14} style={{ color: '#C94B4B' }} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>

      {showModal && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h2>{editingId ? 'Edit Indicator' : 'New Indicator'}</h2>
              <button className="close-btn" onClick={handleClose}>
                <X size={20} />
              </button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="modal-body">
                <div className="form-grid">
                  <div className="form-group full-width">
                    <label>Indicator Name</label>
                    <input
                      type="text"
                      name="name"
                      placeholder="e.g. Children receiving mobility aids"
                      value={formData.name}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label>Output Category</label>
                    <input
                      type="text"
                      name="output_category"
                      placeholder="e.g. Component 2"
                      value={formData.output_category}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label>Frequency</label>
                    <input
                      type="text"
                      name="frequency"
                      placeholder="e.g. Quarterly"
                      value={formData.frequency}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="form-group">
                    <label>Baseline</label>
                    <input
                      type="number"
                      step="0.01"
                      name="baseline"
                      value={formData.baseline}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label>Target</label>
                    <input
                      type="number"
                      step="0.01"
                      name="target"
                      value={formData.target}
                      onChange={handleInputChange}
                      required
                    />
                  </div>
                  <div className="form-group">
                    <label>Actual (Current Value)</label>
                    <input
                      type="number"
                      step="0.01"
                      name="actual"
                      value={formData.actual}
                      onChange={handleInputChange}
                    />
                  </div>
                  <div className="form-group">
                    <label>Unit of Measure</label>
                    <input
                      type="text"
                      name="unit_of_measure"
                      placeholder="e.g. Children, %"
                      value={formData.unit_of_measure}
                      onChange={handleInputChange}
                    />
                  </div>
                </div>
              </div>
              <div className="modal-footer">
                <button type="button" className="btn-secondary" onClick={handleClose}>Cancel</button>
                <button type="submit" className="btn-primary" disabled={saving}>
                  {saving ? 'Saving...' : 'Save Indicator'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Indicators;
